import React, { useState, useEffect } from 'react';
import { useNavigate } from "react-router-dom";

function WarehouseOrders() {

  // Functions
  const navigate = useNavigate();

  let [search, setSearch] = useState("")
  let [sort, setSort] = useState("name")
  let [orders, setOrders] = useState([])
  

  function onSearchChange(e) {
    setSearch(e.target.value)
  }

  function onSortChange(e) {
    setSort(e.target.value)
  }

  function getSortedWarehouseOrdersData() {
    return orders
      .filter((item) => {
        const searchTerm = search.toLowerCase();
        return (
          item.ordernr.toLowerCase().includes(searchTerm) ||
          item.warehousenr.toLowerCase().includes(searchTerm) ||
          item.suppliernr.toLowerCase().includes(searchTerm) ||
          item.orderDate.toLowerCase().includes(searchTerm) ||
          item.statusnr.toLowerCase().includes(searchTerm) ||
          item.deliveryDate.toLowerCase().includes(searchTerm)
        );
      })
      .sort((a, b) => {
        return (a[sort] + "").localeCompare(b[sort] + "");
      });
  }
  return (
    <>
      <div>WarehouseOrders</div>

      <div className="tableFunctions">
        <div className="tableSeachbar">
          <i class="bi bi-search"></i>
          <input class="tableSeachInput" type="text" placeholder="Search" onChange={onSearchChange} value={search}></input>
        </div>

        <div className='sortWithAddFunctions'>
          <select className="tableSort" onChange={onSortChange} value={sort}>
            <option selected value="ordernr">
              Order nr.
              <i className='bi bi-chevron-down'></i>
            </option>
            <option value="name">Name</option>
            <option value="contact">Contact Pers.</option>
          </select>
        </div>
      </div>

      <div className="table-container">
        <table>
          <thead>
            <tr>
              <th>Order nr.</th>
              <th>Warehouse nr.</th>
              <th>Supplier nr.</th>
              <th>Orderdate</th>
              <th>Status nr.</th>
              <th>Deleverydate</th>
            </tr>
          </thead>

          <tbody>
            { orders.length > 0 &&
              getSortedWarehouseOrdersData().map((item) => {
                return <tr key ={item.ordernr}>
                  <td>{item.ordernr}</td>
                  <td>{item.WarehouseOrders}</td>
                  <td>{item.suppliernr}</td>
                  <td>{item.orderDate}</td>
                  <td>{item.statusnr}</td>
                  <td>{item.deliveryDate}</td>
                  
                  
    
                </tr>
              })
            }
          </tbody>
        </table>
      </div>
    </>
  )
}

export default WarehouseOrders
